[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    // GET /api/products - list all
    [HttpGet]
    public IActionResult GetAll() => Ok(_products);

    // GET /api/products/5 - get one
    [HttpGet("{id}")]
    public IActionResult Get(int id) => Ok(_products.First(p => p.Id == id));

    // POST /api/products - create
    [HttpPost]
    public IActionResult Create([FromBody] Product product)
    {
        _products.Add(product);
        return CreatedAtAction(nameof(Get), new { id = product.Id }, product);
    }

    // PUT /api/products/5 - full update
    [HttpPut("{id}")]
    public IActionResult Update(int id, [FromBody] Product product)
    {
        var existing = _products.First(p => p.Id == id);
        existing.Name = product.Name;
        return NoContent();
    }

    // DELETE /api/products/5
    [HttpDelete("{id}")]
    public IActionResult Delete(int id)
    {
        _products.RemoveAll(p => p.Id == id);
        return NoContent();
    }
}

[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    [HttpGet("{id}")]
    public IActionResult Get(int id)
    {
        var order = _repo.Get(id);
        if (order == null)
            return NotFound(); // 404
        return Ok(order); // 200
    }

    [HttpPost]
    public IActionResult Create([FromBody] CreateOrderRequest req)
    {
        if (!ModelState.IsValid)
            return ValidationProblem(ModelState); // 400 with details

        var order = _repo.Create(req);
        return CreatedAtAction(nameof(Get), new { id = order.Id }, order); // 201
    }

    [HttpDelete("{id}")]
    public IActionResult Delete(int id)
    {
        if (!_repo.Exists(id))
            return NotFound(); // 404
        _repo.Delete(id);
        return NoContent(); // 204
    }
}
